<?php
include_once __DIR__.'/includes/session_check.php';require_login_modal();include __DIR__.'/db_connect.php';
if(empty($_SESSION['login_id'])||(int)($_SESSION['login_type']??0)!==1){header('location:login.php');exit;}
if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));
$csrf=$_SESSION['csrf_token'];$school=(int)($_SESSION['login_school_id']??0);$years=[];$selected=0;$s=$conn->prepare('SELECT id,year,is_active FROM academic_year WHERE school_id=? ORDER BY year DESC');$s->bind_param('i',$school);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc()){$years[]=$x;if($x['is_active'])$selected=(int)$x['id'];}$s->close();if(!$selected&&$years)$selected=(int)$years[0]['id'];
?>
<style>
.cp{padding:8px 4px}.cp-head,.cp-heading,.cp-panel-head{display:flex;align-items:center}.cp-head,.cp-panel-head{justify-content:space-between;gap:12px}.cp-head{margin-bottom:14px}.cp-heading{gap:12px}.cp-icon{width:46px;height:46px;border-radius:12px;background:#eaf2ff;color:#2f6fed;display:flex;align-items:center;justify-content:center;font-size:20px}.cp-heading h5{margin:0;font-weight:700;color:#233b52}.cp-heading small{color:#6c757d}.cp-toolbar{display:grid;grid-template-columns:1.1fr 1fr 1fr 1.4fr auto;gap:12px;background:#fff;border:1px solid #e3e8f0;border-radius:12px;padding:14px;margin-bottom:14px}.cp-field label{display:block;font-size:.78rem;font-weight:700;color:#526274;margin-bottom:5px}.cp-field .form-control{height:38px;border-radius:8px}.cp-stats{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:14px}.cp-stat{background:#fff;border:1px solid #e3e8f0;border-radius:12px;padding:13px;display:flex;gap:11px;align-items:center}.cp-stat i{width:38px;height:38px;border-radius:10px;background:#edf3ff;color:#2f6fed;display:flex;align-items:center;justify-content:center}.cp-stat strong{display:block;font-size:1.13rem;color:#233b52}.cp-stat span{font-size:.74rem;color:#6c757d}.cp-panel{background:#fff;border:1px solid #e3e8f0;border-radius:12px;overflow:hidden}.cp-panel-head{padding:12px 14px;border-bottom:1px solid #e9edf4}.cp-body{padding:14px}.cp-bulk{display:none;background:#f3f7ff;border:1px solid #dce7ff;border-radius:9px;padding:10px;margin-bottom:12px;align-items:center;gap:8px}.cp-bulk.show{display:flex}.cp-empty{text-align:center;padding:45px;color:#7a8794}.table td,.table th{vertical-align:middle!important}@media(max-width:1050px){.cp-toolbar{grid-template-columns:repeat(3,1fr)}.cp-stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:700px){.cp-head,.cp-panel-head{align-items:flex-start;flex-direction:column}.cp-toolbar,.cp-stats{grid-template-columns:1fr 1fr}}
</style>
