 <div class="cp-head"><div class="cp-heading"><div class="cp-icon"><i class="fa fa-file-invoice-dollar"></i></div><div><h5>Conceptos de pago</h5><small>Catálogo, asignación y seguimiento financiero por año académico</small></div></div><button class="btn btn-primary" id="new-concept"><i class="fa fa-plus mr-1"></i>Nuevo concepto</button></div>
 <div id="cp-migration" class="alert alert-warning d-none"><strong>Migración pendiente:</strong> ejecuta <code>sql/concepts_module_upgrade.sql</code>.</div>
 <div class="cp-toolbar"><div class="cp-field"><label>Año académico</label><select id="cp-year" class="form-control"><?php foreach($years as $y): ?><option value="<?php echo (int)$y['id']; ?>" <?php echo $selected===(int)$y['id']?'selected':''; ?>><?php echo htmlspecialchars($y['year'].($y['is_active']?' (Activo)':'')); ?></option><?php endforeach; ?></select></div><div class="cp-field"><label>Nivel</label><select id="cp-level" class="form-control"><option value="">Todos</option><option>Inicial</option><option>Primaria</option><option>Secundaria</option></select></div><div class="cp-field"><label>Estado</label><select id="cp-status" class="form-control"><option value="">Todos</option><option>Activo</option><option>Suspendido</option><option>Archivado</option></select></div><div class="cp-field"><label>Buscar</label><input id="cp-search" class="form-control" placeholder="Nombre o descripción"></div><div class="cp-field"><label>&nbsp;</label><button id="cp-reset" class="btn btn-outline-secondary"><i class="fa fa-undo"></i></button></div></div>
 <div class="cp-stats"><div class="cp-stat"><i class="fa fa-list"></i><div><strong id="st-concepts">0</strong><span>Conceptos visibles</span></div></div><div class="cp-stat"><i class="fa fa-check-circle"></i><div><strong id="st-active">0</strong><span>Activos</span></div></div><div class="cp-stat"><i class="fa fa-file-invoice"></i><div><strong id="st-assigned">S/ 0.00</strong><span>Total asignado</span></div></div><div class="cp-stat"><i class="fa fa-hand-holding-usd"></i><div><strong id="st-collected">S/ 0.00</strong><span>Total cobrado</span></div></div><div class="cp-stat"><i class="fa fa-wallet"></i><div><strong id="st-balance">S/ 0.00</strong><span>Saldo pendiente</span></div></div></div>
 <div class="cp-panel"><div class="cp-panel-head"><strong><i class="fa fa-table text-primary mr-2"></i>Catálogo de conceptos</strong><div><button id="cp-export" class="btn btn-sm btn-outline-success"><i class="fa fa-file-excel mr-1"></i>Exportar</button> <button id="cp-audit" class="btn btn-sm btn-outline-secondary"><i class="fa fa-history mr-1"></i>Auditoría</button> <button id="cp-refresh" class="btn btn-sm btn-outline-primary"><i class="fa fa-sync-alt"></i></button></div></div><div class="cp-body"><div class="cp-bulk" id="cp-bulk"><strong><span id="cp-selected">0</span> seleccionados</strong><select id="cp-bulk-status" class="form-control form-control-sm" style="max-width:190px"><option value="">Cambiar estado...</option><option>Activo</option><option>Suspendido</option><option>Archivado</option></select><button id="cp-apply" class="btn btn-sm btn-primary">Aplicar</button><button id="cp-clear" class="btn btn-sm btn-link">Cancelar</button></div><div id="cp-loading" class="text-center py-5"><i class="fa fa-spinner fa-spin fa-2x text-primary"></i></div><div id="cp-results"></div></div></div>
