<div class="modal fade" id="conceptAudit"><div class="modal-dialog modal-xl"><div class="modal-content"><div class="modal-header"><h5 class="modal-title"><i class="fa fa-history mr-2"></i>Auditoría de conceptos</h5><button class="close" data-dismiss="modal">&times;</button></div><div class="modal-body table-responsive"><table class="table table-sm table-bordered"><thead><tr><th>Fecha</th><th>Usuario</th><th>Concepto</th><th>Acción</th><th>Detalle</th></tr></thead><tbody id="cp-audit-body"></tbody></table></div></div></div></div>
<script>(function($){const api='concepts_api.php',csrf=<?php echo json_encode($csrf); ?>;let rows=[],selected={},timer,dataTable=null;
function e(v){return $('<div>').text(v==null?'':v).html()}function money(v){return 'S/ '+Number(v||0).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2})}function bulk(){let n=Object.keys(selected).length;$('#cp-selected').text(n);$('#cp-bulk').toggleClass('show',n>0)}
function load(){$('#cp-loading').show();$('#cp-results').empty();$.getJSON(api,{action:'list',academic_year_id:$('#cp-year').val(),level:$('#cp-level').val(),status:$('#cp-status').val(),search:$('#cp-search').val()}).done(function(r){rows=r.concepts||[];let s=r.stats||{};$('#st-concepts').text(s.concepts||0);$('#st-active').text(s.active||0);$('#st-assigned').text(money(s.assigned));$('#st-collected').text(money(s.collected));$('#st-balance').text(money(s.balance));render()}).fail(function(x){let r=x.responseJSON||{};if(r.migration_required){$('#cp-migration').removeClass('d-none');$('#new-concept,#cp-apply').prop('disabled',true)}$('#cp-results').html('<div class="cp-empty">'+e(r.message||'No se pudieron cargar los conceptos.')+'</div>')}).always(()=>$('#cp-loading').hide())}
function destroyTable(){if(dataTable){dataTable.destroy();dataTable=null}}
function render(){destroyTable();if(!rows.length){$('#cp-results').html('<div class="cp-empty"><i class="fa fa-folder-open fa-3x mb-2"></i><h6>No hay conceptos para estos filtros</h6></div>');return}let h='<div class="table-responsive"><table class="table table-hover" id="cp-table"><thead><tr><th><input type="checkbox" id="cp-all"></th><th>Concepto</th><th>Nivel y grados</th><th>Monto base</th><th>Asignado</th><th>Cobrado</th><th>Saldo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>';rows.forEach(c=>{let badge=c.concept_status==='Activo'?'success':(c.concept_status==='Suspendido'?'warning':'secondary'),locked=['Cerrado','Archivado'].includes(c.year_status);h+='<tr><td><input class="cp-check" type="checkbox" value="'+c.id+'" '+(selected[c.id]?'checked':'')+' '+(locked?'disabled':'')+'></td><td><strong>'+e(c.course)+'</strong><div class="small text-muted">'+e(c.description||'Sin descripción')+' · '+e(c.year)+'</div></td><td>'+e(c.level)+'<div class="small text-muted">'+e(c.grades||'—')+'</div></td><td>'+money(c.total_amount)+'</td><td>'+money(c.assigned_total)+'<div class="small text-muted">'+c.assignment_count+' asignaciones</div></td><td class="text-success">'+money(c.collected_total)+'</td><td class="font-weight-bold">'+money(c.balance)+'</td><td><span class="badge badge-'+badge+'">'+e(c.concept_status)+'</span></td><td><div class="btn-group"><button class="btn btn-sm btn-outline-primary cp-edit" data-id="'+c.id+'" '+(locked?'disabled':'')+'><i class="fa fa-edit"></i></button><button class="btn btn-sm btn-outline-secondary dropdown-toggle" data-toggle="dropdown"></button><div class="dropdown-menu dropdown-menu-right"><a href="#" class="dropdown-item cp-state" data-id="'+c.id+'" data-state="Activo">Activar</a><a href="#" class="dropdown-item cp-state" data-id="'+c.id+'" data-state="Suspendido">Suspender</a><a href="#" class="dropdown-item cp-state" data-id="'+c.id+'" data-state="Archivado">Archivar</a><div class="dropdown-divider"></div><a href="#" class="dropdown-item text-danger cp-delete" data-id="'+c.id+'">Eliminar si está vacío</a></div></div></td></tr>'});$('#cp-results').html(h+'</tbody></table></div>');if($.fn.DataTable){dataTable=$('#cp-table').DataTable({pageLength:15,lengthMenu:[[15,25,50,100],[15,25,50,100]],order:[[1,'asc']],columnDefs:[{orderable:false,targets:[0,8]}],dom:'lrtip',language:{lengthMenu:'Mostrar _MENU_ registros',zeroRecords:'No se encontraron conceptos',info:'Mostrando _START_ a _END_ de _TOTAL_',infoEmpty:'Mostrando 0 registros',infoFiltered:'(filtrado de _MAX_)',paginate:{previous:'Anterior',next:'Siguiente'}}})}bulk()}
$(document).on('change','.cp-check',function(){this.checked?selected[this.value]=1:delete selected[this.value];bulk()});$(document).on('change','#cp-all',function(){rows.forEach(c=>this.checked?selected[c.id]=1:delete selected[c.id]);render()});$('#cp-clear').click(function(){selected={};render()});$('#cp-year,#cp-level,#cp-status').change(function(){selected={};load()});$('#cp-search').on('input',function(){clearTimeout(timer);timer=setTimeout(load,300)});$('#cp-reset').click(function(){$('#cp-level,#cp-status,#cp-search').val('');selected={};load()});$('#cp-refresh').click(load);
$('#new-concept').click(()=>uni_modal('Nuevo concepto de pago','manage_concept.php','large'));$(document).on('click','.cp-edit',function(){uni_modal('Editar concepto de pago','manage_concept.php?id='+$(this).data('id'),'large')});$(document).on('concepts:changed',load);
function post(action,data){data.csrf_token=csrf;return $.post(api+'?action='+action,data,null,'json')}$(document).on('click','.cp-state',function(x){x.preventDefault();let id=$(this).data('id'),state=$(this).data('state');if(confirm('¿Cambiar el concepto a '+state+'?'))post('change_status',{id:id,concept_status:state}).done(r=>{alert_toast(r.message,r.status==1?'success':'danger');if(r.status==1)load()})});$(document).on('click','.cp-delete',function(x){x.preventDefault();let id=$(this).data('id');if(confirm('Solo se eliminará si no tiene historial. De lo contrario será archivado. ¿Continuar?'))post('delete',{id:id}).done(r=>{alert_toast(r.message,r.status==1?'success':'danger');if(r.status==1)load()})});
$('#cp-apply').click(function(){let state=$('#cp-bulk-status').val(),ids=Object.keys(selected);if(!state)return alert_toast('Seleccione un estado.','warning');if(confirm('¿Cambiar '+ids.length+' conceptos a '+state+'?'))post('bulk',{ids:JSON.stringify(ids),concept_status:state,academic_year_id:$('#cp-year').val()}).done(r=>{alert_toast(r.message,r.status==1?'success':'danger');if(r.status==1){selected={};load()}})});
$('#cp-export').click(function(){let ids=Object.keys(selected);location='export_concepts.php?'+$.param({academic_year_id:$('#cp-year').val(),level:$('#cp-level').val(),status:$('#cp-status').val(),search:$('#cp-search').val(),ids:ids.join(',')})});$('#cp-audit').click(function(){$('#cp-audit-body').html('<tr><td colspan="5" class="text-center"><i class="fa fa-spinner fa-spin"></i></td></tr>');$('#conceptAudit').modal('show');$.getJSON(api,{action:'audit',academic_year_id:$('#cp-year').val()}).done(function(r){let h='';(r.audit||[]).forEach(x=>h+='<tr><td>'+e(x.created_at)+'</td><td>'+e(x.user_name)+'</td><td>'+e(x.concept_name)+'</td><td>'+e(x.action)+'</td><td><small>'+e(x.details||'')+'</small></td></tr>');$('#cp-audit-body').html(h||'<tr><td colspan="5" class="text-center text-muted">Sin movimientos.</td></tr>')})});load();})(jQuery);</script>
